import pandas as pd
import numpy as np

train = pd.read_csv('b3_te_zt_extrapolation_train.csv')
pool = pd.read_csv('b3_te_zt_extrapolation_pool.csv')
comp = [c for c in train.columns if c not in ['T','target']]
train_c = train[train['target']<5].copy()

def classify(row):
    d = row[comp]
    # order matters - more specific first
    if row['O']>0.15 and row['Se']>0.15 and row['Cu']>0.15 and row['Bi']>0.15:
        return 'BiCuSeO'
    if row['Cu']>0.5 and row['Se']>0.2:
        return 'Cu2Se'
    if row['Pb']>0.3 and row['Te']>0.3:
        return 'PbTe'
    if row['Pb']>0.3 and row['Se']>0.2:
        return 'PbSe'
    if row['Ge']>0.3 and row['Te']>0.3:
        return 'GeTe'
    if row['Sn']>0.3 and row['Te']>0.3:
        return 'SnTe'
    if row['Sn']>0.3 and row['Se']>0.3:
        return 'SnSe'
    if row['Sn']>0.3 and row['S']>0.3:
        return 'SnS'
    if row['Pb']>0.3 and row['S']>0.3:
        return 'PbS'
    if row['Sb']>0.55 and row['Co']>0.1:
        return 'CoSb3'
    if row['Sb']>0.5 and row['Fe']>0.1:
        return 'FeSb'
    if row['Mg']>0.5:
        return 'Mg2X'
    if row['Ni']>0.2 and (row['Ti']>0.05 or row['Zr']>0.05) and row['Sn']>0.2:
        return 'HH_XNiSn'
    if row['Co']>0.2 and row['Ti']>0.2 and row['Sb']>0.2:
        return 'HH_TiCoSb'
    if row['O']>0.4:
        return 'oxide'
    if row['Si']>0.4 and row['Ge']>0.05:
        return 'SiGe'
    if row['Si']>0.4:
        return 'silicide'
    if row['Sb']>0.2 and row['Te']>0.4:
        return 'BiSbTe'
    if row['Ag']>0.15 and row['Sb']>0.15 and row['Te']>0.3:
        return 'AgSbTe'
    if row['Ge']>0.5:
        return 'Ge-rich'
    if row['Sb']>0.25 and row['Co']>0.25:
        return 'CoSb_HH'
    return 'other'

train_c['fam'] = train_c.apply(classify, axis=1)
pool['fam'] = pool.apply(classify, axis=1)

print('=== TRAIN family stats by T ===')
print(train_c.groupby(['fam','T'])['target'].agg(['count','mean','median','max']).to_string())

print('\n=== POOL family counts ===')
print(pool['fam'].value_counts())

print('\n=== POOL by family ===')
for fam, g in pool.groupby('fam'):
    print(f'\n{fam}: {list(g.candidate_id)}')

# For each family, estimate zT vs T from train
print('\n=== Family T trends (mean zT) ===')
for fam in sorted(train_c['fam'].unique()):
    g = train_c[train_c['fam']==fam]
    means = g.groupby('T')['target'].mean()
    maxs = g.groupby('T')['target'].max()
    print(f"{fam:12s} mean={dict((int(k),round(v,3)) for k,v in means.items())}  max={dict((int(k),round(v,3)) for k,v in maxs.items())} n={len(g)}")
